import sys
input = sys.stdin.read

def solve(n, k):
    powers = []
    for i in range(60, -1, -1):
        if n >= (1 << i):
            powers.append(i)
            n -= (1 << i)

    if len(powers) > k:
        print("No")
        return

    while len(powers) < k:
        for i in range(len(powers)):
            if powers[i] > 0:
                powers[i] -= 1
                powers.append(powers[i])
                break

    powers.sort(reverse=True)
    print("Yes")
    print(" ".join(map(str, powers)))

def main():
    data = input().strip()
    n, k = map(int, data.split())
    solve(n, k)

main()

