import sys

input = sys.stdin.read
data = input().split()

n, k = map(int, data)

if n % 2 == 1 or n < 2 ** k:
    print("No")
else:
    print("Yes")
    result = []
    for i in range(k):
        if n >= 2 ** (k - i - 1):
            result.append(k - i - 1)
            n -= 2 ** (k - i - 1)
        else:
            result.append(0)
    print(*result)
